from pathlib import Path
import json,zipfile,html
out=Path(__file__).parent;kit=out/'kit';kit.mkdir(exist_ok=True)
prompt='''Create an original 12-second motion graphic for [PRODUCT], using Remotion.\nAudience: [AUDIENCE]. Main message: [ONE BENEFIT].\nFormat: 1080x1920, 30fps. Leave the bottom 280px clear for platform controls.\nPalette: ink #142033, warm white #f6f1e8, lime #b7ff64. Use licensed fonts.\n0–3s: reveal the product name and one short benefit with staggered type.\n3–7s: demonstrate one feature with original geometric UI elements. Gentle camera push.\n7–10s: resolve into the benefit with a clean slide transition.\n10–12s: hold the final call to action with no new competing elements.\nUse frame-based animation. Keep text legible on a phone.\nDo not copy another creator’s logo, assets, music or composition.\nProvide editable source, a preview, and a note listing any external assets and licenses.\nReview the render for spelling, contrast, clipping, timing and audio before publishing.\n'''
check='''MOTION REVIEW CHECKLIST\n[ ] One audience, one message, one CTA\n[ ] Original or licensed assets and music\n[ ] Product details and any statistics verified\n[ ] Text readable on a real phone\n[ ] No clipping at any scene boundary\n[ ] Frame-driven animation and clean transitions\n[ ] Final frame held long enough to read\n[ ] Audio balanced; captions match narration\n[ ] Review the actual exported file\n[ ] Approval before publication\n'''
(kit/'starter-prompt.txt').write_text(prompt);(kit/'review-checklist.txt').write_text(check)
(kit/'sources.txt').write_text('Source library: https://prompt-motion.com\nLibrary methodology: https://prompt-motion.com/blog/ai-motion-graphics-prompts\nExamples belong to their creators. Check rights before reusing assets.\nOriginal starter brief and checklist by withhammad. No exact-result guarantee.\n')
with zipfile.ZipFile(out/'ai-motion-starter-kit.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in kit.iterdir():z.write(p,p.name)
(out/'resource.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Motion Starter Kit | withhammad</title><style>*{box-sizing:border-box}body{margin:0;background:#142033;color:#f6f1e8;font:18px/1.6 system-ui}main{max-width:860px;padding:60px 24px;margin:auto}h1{font-size:clamp(38px,7vw,70px);line-height:1.04}a{color:#b7ff64}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f1e8;color:#142033;padding:26px;border-radius:20px;font:16px/1.7 monospace}button,.download{display:inline-block;border:0;border-radius:12px;padding:14px 22px;background:#b7ff64;color:#142033;font-weight:700;text-decoration:none;cursor:pointer}small{color:#c2cbd3}</style><main><small>WITHHAMMAD / ORIGINAL STARTER KIT</small><h1>Give your motion<br>a clear brief.</h1><p>Start with a useful example, then define your own audience, message, assets and timing.</p><p><a class="download" href="ai-motion-starter-kit.zip" download>Download the kit</a></p><h2>1. Explore examples</h2><p><a href="https://prompt-motion.com" target="_blank" rel="noopener">Browse Prompt Motion</a>. Each entry credits its creator. Review the prompt as a design brief; do not assume permission to reuse the finished video or assets.</p><h2>2. Adapt this original prompt</h2><button onclick="navigator.clipboard.writeText(document.querySelector('pre').innerText).then(()=>this.innerText='Copied')">Copy starter prompt</button><pre>'''+html.escape(prompt)+'''</pre><h2>3. Review the result</h2><pre>'''+html.escape(check)+'''</pre><p>This is an independent learning resource. Results depend on the model, tools, assets and iteration. No exact recreation or performance guarantee.</p><small>Draft resource prepared for reel approval; not yet deployed.</small></main></html>''')
resource='https://withhammad.com/resources/ai-motion-starter-kit'
base='Better AI motion graphics start with a clearer brief.\n\nBrowse an example, study the prompt, then define your own product, palette, timing and final frame. Review the output and iterate.\n\nThis reel includes a live Prompt Motion walkthrough and an original Remotion demonstration. AI presenter.\n\n'
caps={p:base+('Follow @with.hammad and comment MOTION for my original starter brief and checklist.' if p=='instagram' else 'Get the starter kit: '+resource+'\nFollow for practical AI builds.')+'\n\n#AIMotionGraphics #Remotion #MotionDesign #ClaudeCode' for p in ['instagram','youtube','linkedin','facebook','tiktok']}
caps['x']='Better AI motion starts with a clearer brief: product, palette, timing and final frame. Original Remotion demo + Prompt Motion walkthrough. AI presenter. Kit: '+resource+' #MotionDesign'
(out/'captions-and-hooks.json').write_text(json.dumps({'status':'draft_for_owner_review','resource_status':'local_not_deployed','hook':'Want better AI motion graphics? Start with a finished example and the prompt behind it!','youtube_title':'Better AI Motion Graphics: From Example to Original Brief','thumbnail':'STEAL THE STRUCTURE. MAKE IT YOURS.','keyword':'MOTION','captions':caps},indent=2)+'\n')
(out/'manychat-plan.json').write_text(json.dumps({'status':'draft_only_not_created','keyword':'MOTION','trigger':'Only this reel, after final approval and publication; never all posts','message':'Thanks for commenting MOTION! Follow @with.hammad for practical AI builds. Here is my starter brief and review checklist: '+resource+'?utm_source=instagram&utm_medium=dm&utm_campaign=motion','resource_status':'local_not_deployed','enable_after':'Owner approval, resource deployment, actual reel exists, specific post binding verified'},indent=2)+'\n')
(out/'production.json').write_text(json.dumps({'job':'motion20261020','status':'in_production_avatar_processing','reference':'https://www.instagram.com/reel/DerldXdPE38/','reference_duration':29.909,'language':'English','avatar_id':'5dfa03f53ae54f919040a26a953b7f4b','presenter_box':[340,192],'approval_required':True,'upload_status':'not_uploaded_not_scheduled','resource_status':'local_not_deployed','keyword':'MOTION','studio':'http://localhost:3018/MotionLibrary'},indent=2)+'\n')
(out/'research.md').write_text('''# Reference and factual checks\nReference: https://www.instagram.com/reel/DerldXdPE38/ — Nick Saraev, 19 October 2026, 29.909 seconds.\nVisuals: library discovery, category browsing, prompt examples, brand adaptation, comment CTA. Original edit keeps presenter small.\nVerified primary site: https://prompt-motion.com — gallery with creator credits and prompts; product UI, charts and kinetic type categories.\nhttps://prompt-motion.com/blog/ai-motion-graphics-prompts describes 230 examples. Reference caption claims 500+ but reference frames show 230; omit changing/unsupported count.\nAvoid claims of exact recreation or matching sound effects. Show original Remotion demo and identify it as such. Never present it as proof that the source prompt generated an identical result.\n''')
